const roles = ['Estimator', 'Project Manager', 'Business Development', 'Preconstruction Manager'];
const first = ['James','Maria','David','Linda','Robert','Susan','Michael','Karen'];
const last  = ['Smith','Johnson','Williams','Brown','Jones','Garcia','Miller','Davis'];
const pick = a => a[Math.floor(Math.random()*a.length)];

return items.map(item => {
  const p = item.json;
  const companyName = `${pick(last)} Construction Group`;
  const domain = companyName.toLowerCase().replace(/[^a-z]/g,'') + '.com';
  const fn = pick(first), ln = pick(last);
  return {
    json: {
      project_id: p.id,
      company_name: companyName,
      domain: domain,
      contact_name: `${fn} ${ln}`,
      role: pick(roles),
      email: `${fn.toLowerCase()}.${ln.toLowerCase()}@${domain}`,
      confidence: 60 + Math.floor(Math.random()*40)
    }
  };
});

